(function(){'use strict';
/* STAGING LOCALE BUILD (de) — generated by scripts/build_locale_staging.py from assets/growth/tools.js.
 * Only string literals and display formatting differ. Formulas, weights, thresholds, clamping and toFixed() rounding are
 * unchanged; fx() formats the already-rounded value with Intl.NumberFormat. Parity: scripts/locale_tools_parity.js. */
const LOC="de-DE";
const fx=(n,d)=>new Intl.NumberFormat(LOC,{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(n.toFixed(d)));
const PLC=n=>(n===1?"{n} Signal ausgewählt":(n>=2&&n<=4)?"{n} Signale ausgewählt":"{n} Signale ausgewählt").replace('{n}',String(n));
const VCS_LINK="„{phrase}“ in VC Says";

const $=id=>document.getElementById(id), num=id=>{const el=$(id);if(!el)return 0;let v=Number(el.value);if(!Number.isFinite(v))return 0;if(el.min!==''&&Number.isFinite(Number(el.min)))v=Math.max(Number(el.min),v);if(el.max!==''&&Number.isFinite(Number(el.max)))v=Math.min(Number(el.max),v);return v};
const money=(n)=>new Intl.NumberFormat(LOC,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number.isFinite(n)?n:0);
const pct=(n)=>fx(Number.isFinite(n)?n:0,1)+'\u00a0%';
function event(name,props={}){try{if(window.posthog&&typeof window.posthog.capture==='function')window.posthog.capture(name,props);if(typeof window.gtag==='function')window.gtag('event',name,props)}catch(e){}}
function bindCalculate(id,fn){const b=$(id);if(!b)return;b.addEventListener('click',()=>{fn();event('tfg_tool_completed',{tool_slug:document.body.dataset.tool||'unknown'})});}
function set(id,value){const el=$(id);if(el)el.textContent=String(value)}
function copyText(txt,button){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(txt).then(()=>{if(button)button.textContent="Kopiert ✓";event('tfg_tool_result_copied',{tool_slug:document.body.dataset.tool||'unknown'})}).catch(()=>fallback())}else fallback();function fallback(){let ta=document.createElement('textarea');ta.value=txt;ta.style.position='fixed';ta.style.top='-9999px';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');if(button)button.textContent="Kopiert ✓";event('tfg_tool_result_copied',{tool_slug:document.body.dataset.tool||'unknown'})}catch(e){if(button)button.textContent="Text markieren und kopieren"}ta.remove()}}
const signalItems=[
{key:'next',label:"Schlägt ein konkretes nächstes Meeting oder einen Termin vor",weight:4,group:'action'},
{key:'partner',label:"Stellt Sie einem weiteren Partner oder einer entscheidenden Person vor",weight:4,group:'action'},
{key:'diligence',label:"Fordert konkrete Due-Diligence-Unterlagen oder Kundenreferenzen an",weight:3,group:'action'},
{key:'champion',label:"Erklärt klar, wie der interne Entscheidungsprozess abläuft",weight:2,group:'action'},
{key:'question',label:"Stellt konkrete Rückfragen zu Ihrem Geschäft",weight:1,group:'interest'},
{key:'polite',label:"Sagt „interessant, haltet uns auf dem Laufenden“ ohne nächsten Schritt",weight:-2,group:'caution'},
{key:'noresponse',label:"Hat einen zugesagten Antworttermin verstreichen lassen, ohne sich zu melden",weight:-2,group:'caution'},
{key:'wrong',label:"Sagt, dass Phase, Branche, Region oder Ticketgröße nicht passen",weight:-4,group:'caution'},
];
function initSignals(){const wrap=$('signals-list');if(!wrap)return;signalItems.forEach(s=>{let lab=document.createElement('label');lab.className='formcheck';let ch=document.createElement('input');ch.type='checkbox';ch.name='signal';ch.value=s.key;lab.appendChild(ch);lab.append(document.createTextNode(s.label));wrap.appendChild(lab)});bindCalculate('signals-calculate',()=>{const chosen=[...document.querySelectorAll('input[name="signal"]:checked')].map(x=>signalItems.find(s=>s.key===x.value));const score=chosen.reduce((sum,x)=>sum+x.weight,0);const actions=chosen.filter(x=>x.group==='action').length;let status="Zu wenig Signal",desc="Es gibt noch nicht genug Hinweise auf einen konkreten Prozess. Fragen Sie, ob Sie zum Investor passen und was der nächste Entscheidungspunkt ist.",next="Senden Sie ein kurzes, konkretes Follow-up mit einem passenden nächsten Schritt und führen Sie die Gespräche mit anderen Investoren weiter.";if(chosen.some(x=>x.key==='wrong')){status="Wahrscheinlich grundsätzlich unpassend";desc="Eine ausdrücklich fehlende Passung bei Phase, Investmentthese, Region oder Ticketgröße wiegt schwerer als ein freundlicher Ton.";next="Bedanken Sie sich, fragen Sie nach einem passenderen Kollegen oder Fonds und nehmen Sie die Gelegenheit aus Ihrer aktiven Pipeline."}else if(score>=5&&actions>=2){status="Belastbare Prozesssignale";desc="Mehrere konkrete Schritte deuten auf eine echte Prüfung hin; eine Investition garantieren sie trotzdem nicht.";next="Halten Sie Zuständigkeiten, Unterlagen und Termine schriftlich fest. Treiben Sie Ihre anderen Gespräche parallel weiter."}else if(score>=2&&actions>=1){status="Erste Anzeichen von Interesse";desc="Ein konkreter Schritt sagt mehr aus als Komplimente, der Prozess ist aber noch nicht aussagekräftig.";next="Erfüllen Sie die Anfrage und fragen Sie, welche Entscheidung als Nächstes ansteht und bis wann."}else if(score<0){status="Schwache oder nachlassende Dynamik";desc="Höfliches Interesse ohne Taten oder nicht eingehaltene Zusagen erfordern Klärung statt optimistischer Deutung.";next="Teilen Sie ein substanzielles Update und bitten Sie um ein klares Ja oder Nein zur Fortsetzung; erfinden Sie keine Fristen."}const rel=$('signal-related');if(rel){const has=k=>chosen.some(x=>x.key===k);const id=has('wrong')?'not-right-fit':has('noresponse')?'investor-ghosting':has('partner')?'partner-introduction':has('next')?'second-meeting':has('polite')?'keep-in-touch':null;rel.textContent='';if(id)rel.appendChild(vcSaysLink(id,"Passender Leitfaden zur Formulierung: "));else{const a=document.createElement('a');a.href="/de/vc-says";a.textContent="VC Says durchsuchen: typische Investorenformulierungen und passende Antworten";rel.appendChild(a)}}set('signal-status',status);set('signal-desc',desc);set('signal-next',next);set('signal-count',PLC(chosen.length));$('signal-meter').style.width=Math.max(5,Math.min(100,(score+8)*5))+'%';});}
function initPipeline(){if(!$('pipeline-calculate'))return;const run=()=>{const leads=num('pipe-leads'), r1=num('pipe-r1')/100,r2=num('pipe-r2')/100,r3=num('pipe-r3')/100,r4=num('pipe-r4')/100;let first=leads*r1,second=first*r2,terms=second*r3,closed=terms*r4;set('pipe-meetings',fx(first,1));set('pipe-deep',fx(second,1));set('pipe-terms',fx(terms,2));set('pipe-closes',fx(closed,2));set('pipe-close-rate',pct(leads>0?closed/leads*100:0));let target=Math.max(.0000001,r1*r2*r3*r4);set('pipe-needed',Math.ceil(1/target).toLocaleString(LOC));set('pipe-note',terms<1?"Unter diesen Annahmen ist weniger als ein Term Sheet zu erwarten. Verbessern Sie Passung, Konversion oder Outreach-Volumen; Ergebnisse sind nicht garantiert.":"Dies ist ein Erwartungswertmodell, keine Vorhersage tatsächlicher Zusagen. Bei kleinen Zahlen können die Ergebnisse stark schwanken.");};bindCalculate('pipeline-calculate',run);run();}
function initRunway(){if(!$('runway-calculate'))return;const run=()=>{const cash=num('run-cash'),net=Math.max(0,num('run-expenses')-num('run-revenue')),months=num('run-months'),one=num('run-onetime'),buffer=num('run-buffer')/100,pre=num('run-pre');const core=Math.max(0,net*months+one-cash),raise=core*(1+buffer),post=pre+raise,dil=post>0?raise/post*100:0,existing=net>0?cash/net:Infinity;set('run-net',money(net));set('run-existing',Number.isFinite(existing)?fx(existing,1):"Kein Netto-Burn");set('run-raise',money(raise));set('run-dilution',pct(dil));set('run-post',money(post));set('run-pool',money(raise-core));set('run-note',pre<=0?"Geben Sie eine positive Pre-Money-Bewertung ein, um die vereinfachte Verwässerung zu berechnen.":"Nur eine illustrative Priced Round: ohne Mitarbeiterbeteiligungspool, SAFEs, Wandeldarlehen, Gebühren und Änderungen beim Burn. Klären Sie die Konditionen mit Ihren Beratern.");};bindCalculate('runway-calculate',run);run();}
const templates={
 meeting:{subject:"Vielen Dank für das heutige Gespräch – [Firmenname]",intro:"vielen Dank für das heutige Gespräch und Ihre Einschätzung zum Thema [Thema].",mid:"Wie besprochen sende ich Ihnen [zugesagte Unterlagen]. Unser wichtigstes Update: [Fortschritt].",ask:"Wäre als nächster Schritt [konkreter nächster Schritt] sinnvoll?"},
 tooearly:{subject:"Re: [Firmenname] – Fortschritt beim Meilenstein",intro:"vielen Dank für Ihr offenes Feedback, dass wir für Ihre aktuellen Investitionskriterien womöglich noch zu früh sind.",mid:"Seit unserem letzten Gespräch haben wir Folgendes erreicht: [Fortschritt]. Mein Fokus liegt auf dem Meilenstein, den Sie angesprochen haben: [Meilenstein].",ask:"Würde uns dieser Meilenstein näher an Ihre Investitionsschwelle bringen, oder gibt es eine andere Lücke, die wir schließen sollten?"},
 quiet:{subject:"Kurzes Update zu [Firmenname]",intro:"ich möchte an unser Gespräch zum Thema [Thema] anknüpfen.",mid:"Ein kurzes Update seit unserem Gespräch: [Fortschritt].",ask:"Besteht weiterhin Interesse, das Gespräch fortzusetzen, oder soll ich mich wieder melden, sobald wir diesen Meilenstein erreicht haben: [Meilenstein]? Beide Antworten helfen mir weiter."},
 update:{subject:"[Firmenname] – Update: [Fortschritt]",intro:"nochmals vielen Dank für Ihren Vorschlag, nach unserem Gespräch zum Thema [Thema] in Kontakt zu bleiben.",mid:"Die wichtigste Entwicklung seit unserem Gespräch: [Fortschritt]. Als Nächstes arbeiten wir auf diesen Meilenstein hin: [Meilenstein].",ask:"Möchten Sie weiterhin unsere kurzen Investoren-Updates erhalten, oder gibt es eine bestimmte Kennzahl, über die Sie gezielt informiert werden möchten?"},
 notfit:{subject:"Re: [Firmenname] – vielen Dank",intro:"vielen Dank für Ihre klare Rückmeldung zur Passung – ich weiß es sehr zu schätzen, dass Sie uns nicht im Unklaren lassen.",mid:"Falls Sie einen Moment Zeit haben: Lag es vor allem an Phase, Branche oder Region? Das hilft mir, mich auf passendere Investoren zu konzentrieren.",ask:"Wenn Ihnen ein Fonds einfällt, der typischerweise in Unternehmen wie unseres investiert, wäre ich für einen Hinweis sehr dankbar."},
 nolead:{subject:"[Firmenname] – Struktur der Runde",intro:"vielen Dank für den klaren Hinweis, dass für Sie zunächst ein Lead-Investor feststehen sollte.",mid:"Wir konzentrieren uns jetzt darauf, einen Lead-Investor zu gewinnen. Unser wichtigstes Update: [Fortschritt].",ask:"Angenommen, wir gewinnen einen Lead zu Konditionen in der besprochenen Größenordnung: Welche Ticketgröße würden Sie in Betracht ziehen, und haben Sie Anforderungen an den Lead? Über Kontakte zu Fonds, die in unserer Phase Runden anführen, würde ich mich sehr freuen."},
 cold:{subject:"[Firmenname] – kurzes Follow-up",intro:"ich knüpfe an meine Nachricht zu [Firmenname] an – wir helfen [Kunde], [Ergebnis] zu erreichen.",mid:"Eine relevante Neuigkeit: [Fortschritt].",ask:"Passt das in Ihren aktuellen Investitionsfokus? Bei Interesse sende ich Ihnen gern eine kompakte Übersicht."}
};
/* Shared VC Says signal IDs (data/vc_signals.expanded.json). tpl = Follow-up Builder scenario. */
const VC_SAYS={'too-early':{phrase:"Für uns seid ihr noch zu früh dran.",tpl:'tooearly'},'not-right-fit':{phrase:"Das passt für uns leider nicht.",tpl:'notfit'},'keep-in-touch':{phrase:"Lasst uns in Kontakt bleiben.",tpl:'update'},'circle-back-next-quarter':{phrase:"Meldet euch gern im nächsten Quartal wieder.",tpl:'update'},'send-deck':{phrase:"Schickt mir gern mal euer Deck.",tpl:'meeting'},'second-meeting':{phrase:"Lasst uns einen Folgetermin vereinbaren.",tpl:'meeting'},'partner-introduction':{phrase:"Ich würde euch gern einem meiner Partner vorstellen.",tpl:'meeting'},'need-more-traction':{phrase:"Wir müssen erst mehr Traction sehen.",tpl:'tooearly'},'no-lead-investor':{phrase:"Meldet euch wieder, wenn ihr einen Lead habt.",tpl:'nolead'},'investor-ghosting':{phrase:"Keine Antwort, auch nach zweimaligem Nachfassen.",tpl:'quiet'}};
function signalFromQuery(){try{const id=new URLSearchParams(location.search).get('signal');return id&&Object.prototype.hasOwnProperty.call(VC_SAYS,id)?id:null}catch(e){return null}}
function vcSaysLink(id,prefix){const p=document.createElement('span');p.append(document.createTextNode(prefix));const a=document.createElement('a');a.href="/de/vc-says/"+id;a.textContent=VCS_LINK.replace('{phrase}',VC_SAYS[id].phrase.replace(/[.?!]$/,''));p.appendChild(a);p.append(document.createTextNode('.'));return p}
function clean(str,alt){let x=(str||'').trim().replace(/[\r\n]+/g,' ').slice(0,450);return x||alt}
function initFollowup(){if(!$('followup-calculate'))return;const sig=signalFromQuery();if(sig){const sel=$('follow-type');if(sel&&[...sel.options].some(o=>o.value===VC_SAYS[sig].tpl))sel.value=VC_SAYS[sig].tpl;const note=$('follow-signal-note');if(note){note.textContent='';note.appendChild(vcSaysLink(sig,"Situation vorausgewählt anhand des Eintrags in VC Says: "));note.hidden=false}event('tfg_followup_signal_prefill',{signal_id:sig})}const run=()=>{const type=$('follow-type').value,t=templates[type],company=clean($('follow-company').value,'[Firmenname]'),person=clean($('follow-name').value,'[Name des Investors]'),topic=clean($('follow-topic').value,"Geschäftsmodell und Markt"),progress=clean($('follow-progress').value,"[konkreter, überprüfbarer Fortschritt]"),milestone=clean($('follow-milestone').value,"[vereinbarter Meilenstein]"),next=clean($('follow-next').value,"ein kurzes Folgegespräch");let subs={subject:t.subject,intro:t.intro,mid:t.mid,ask:t.ask};for(let k in subs){subs[k]=subs[k].replaceAll('[Firmenname]',company).replaceAll('[Thema]',topic).replaceAll('[Fortschritt]',progress).replaceAll('[Meilenstein]',milestone).replaceAll('[konkreter nächster Schritt]',next)}const out=`Betreff: ${subs.subject}\n\nHallo ${person},\n\n${subs.intro}\n\n${subs.mid}\n\n${subs.ask}\n\nViele Grüße\n[Ihr Name]`; $('follow-output').value=out;};bindCalculate('followup-calculate',run);$('follow-copy').addEventListener('click',function(){copyText($('follow-output').value,this)});run();}
function init(){initSignals();initPipeline();initRunway();initFollowup();document.querySelectorAll('a[href="/#join"],a[href="/#join"],a.button[href="/"],a[data-signup-cta]').forEach(a=>a.addEventListener('click',()=>event('tfg_signup_cta_clicked',{source_path:location.pathname,tool_slug:document.body.dataset.tool||undefined,article_slug:document.body.dataset.article||undefined})));
if(document.body.dataset.tool){event('tfg_tool_viewed',{tool_slug:document.body.dataset.tool,pathname:location.pathname});}
if(document.body.dataset.article){event('tfg_article_viewed',{article_slug:document.body.dataset.article,pathname:location.pathname});}let tracked=false;const main=document.querySelector('main');if(main)main.addEventListener('input',()=>{if(!tracked&&document.body.dataset.tool){event('tfg_tool_started',{tool_slug:document.body.dataset.tool});tracked=true}},{once:true});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
